package com._8x8.herd.device_logs.processor.indexing;

/**
 * What happened to one record. A record that is not done leaves its message on the queue, so it is retried and, after
 * the queue's redrive count, moved to the DLQ.
 */
public enum IndexingOutcome {
    INDEXED(true),
    ALREADY_INDEXED(true),
    UNPARSEABLE_KEY(false),
    METADATA_UNREADABLE(false),
    LOOKUP_FAILED(false),
    WRITE_FAILED(false);

    private final boolean done;

    IndexingOutcome(boolean done) {
        this.done = done;
    }

    /**
     * Whether the row is in the index, so the record's message may be deleted.
     */
    public boolean done() {
        return done;
    }
}
